import{_ as a}from"./chunks/connect.BTLErx-Y.js";import{_ as t,o as n,c as o,a2 as i}from"./chunks/framework.CqGS6Fr9.js";const f=JSON.parse('{"title":"Connecting and signing in","description":"","frontmatter":{"pageId":"players/connect","contentRevision":6},"headers":[],"relativePath":"en/players/connect.md","filePath":"en/players/connect.md"}'),r={name:"en/players/connect.md"};function s(l,e,c,d,h,p){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="connecting-and-signing-in" tabindex="-1">Connecting and signing in <a class="header-anchor" href="#connecting-and-signing-in" aria-label="Permalink to &quot;Connecting and signing in&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><img class="wiki-art" src="'+a+'" alt="Two colonies connect to the server over a secure connection." width="960" height="440"><p class="wiki-caption">Two colonies connect to the server over a secure connection.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Process diagram"><li><strong>Endpoint and TLS</strong><span>Verify host and fingerprint.</span></li><li><strong>Personal login</strong><span>Steam or an allowed password account.</span></li><li><strong>Collection</strong><span>Diff → approved install → restart → check.</span></li><li><strong>Colony</strong><span>Current server save or a new colony.</span></li></ol><p>Add the host and port in <strong>Multiplayer</strong> (default 25560). Obtain the address from the administrator; the browser panel URL and game endpoint need not match. A server-wide password, if configured, is additional to personal authentication.</p><p>Steam login uses a Steam ticket. Password login is available only when enabled by the server; credentials belong to that server. A new certificate is remembered after trust is granted. If its pin changes, confirm the certificate replacement with the administrator first.</p><p>After login the server loads your saved colony, offers a new colony, or shows modpack differences. Resolve the listed differences and reconnect.</p><p>After an administrator rolls back the colony, return to the main menu and sign in again. The client downloads the selected server save, keeps its original custody proof and saves future progress in the new write epoch. A newer local pending save is kept separately.</p><h2 id="login-flow" tabindex="-1">Login steps: certificate, account, colony <a class="header-anchor" href="#login-flow" aria-label="Permalink to &quot;Login steps: certificate, account, colony {#login-flow}&quot;">​</a></h2><ol><li>Open a saved server or enter the exact host/port. A browser panel URL can differ from the game endpoint.</li><li>On first TLS contact, compare the fingerprint with the administrator through another channel. Trust only after verification. A changed pin requires a separate stop, not an automatic continue.</li><li>Enter the shared server password if enabled. It does not replace a Steam ticket or personal password.</li><li>For Steam, wait for ticket verification; temporary rejection may retry automatically. Password accounts belong to this server, which must allow that authentication method.</li><li>Complete collection checks. The server then loads the existing colony or offers a new one. If you expected an old colony, check account/address before creating anything.</li></ol><p><strong>Success:</strong> the home map is loaded, connection active, with no unfinished recovery. Public player names and account logins are not interchangeable.</p><h2 id="login-refusal" tabindex="-1">Distinguish temporary waiting from a final refusal <a class="header-anchor" href="#login-refusal" aria-label="Permalink to &quot;Distinguish temporary waiting from a final refusal {#login-refusal}&quot;">​</a></h2><p>“Waiting for Steam to accept the login” is a Steam wait, not save corruption. “login details are invalid” requires checking credentials. “This account logged in from another place” fences this copy: do not continue it as an independent timeline.</p><p>A normal drop pauses the game and reconnects: first after a second, then less often, up to once a minute. After two minutes you may wait or return to the menu; retries continue behind the dialog. A final refusal, such as a ban or untrusted replacement certificate, requires the menu and fixing its cause. Preserve local state rather than replacing it with another colony.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>Do not disable TLS to work around certificate errors. Never send personal passwords in chat. For a temporary Steam refusal, let authentication retry rather than creating many accounts.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./modpacks">Server modpacks</a></li><li><a href="./../admins/security-auth">TLS, authentication and permissions</a></li><li><a href="./troubleshooting">Player troubleshooting</a></li></ul>',20)])])}const m=t(r,[["render",s]]);export{f as __pageData,m as default};
